		#region CloseLinesButton_Click

		void CloseLinesButton_Click(object sender, EventArgs e)
		{
			if (Stocktake.IsInDatabase)
			{
				if (StocktakeFilterStipUserControl.Grid.SelectedRowCount > 0)
				{
					var selectedLines = StocktakeFilterStipUserControl.Grid.SelectedElements;

					if (!Stocktake.CloseLines(Array.ConvertAll(selectedLines, s => (WhsStocktakeLine)s)))
					{
						Globals.Message.ShowError(Res.GetString("0a757488-9bbf-4526-975b-f76c2c18a786", "You must correct validation errors in selected lines."));
					}
				}
				else
				{
					Globals.Message.ShowError(Res.GetString("be6b49a5-2e3f-48bd-bf0a-8ee4fc87132a", "Please select the lines you wish to close."));
				}
			}
			else
			{
				Globals.Message.ShowError(Res.GetString("b3ea5b8c-a8ee-468b-ae5f-0ffdd363fffe", "You must save the Stocktake/Cycle Count before any Stocktake/Cycle Count lines can be closed."));
			}
		}

