		#region LoadButton_Click

		void LoadButton_Click(object sender, EventArgs e)
		{
			var stocktake = Stocktake;
			stocktake.Validation.ValidateWS_WW_Whs();
			stocktake.Validation.ValidateWS_OH_Client();
			stocktake.Validation.ValidateLocationString();

			if (!stocktake.IsLoaded)
			{
				if (stocktake.WS_WW_WhsInfo.HasErrors())
				{
					Globals.Message.ShowError(stocktake.WS_WW_WhsInfo.GetErrors().GetFirstMessage());
				}
				else if (stocktake.WS_OH_ClientInfo.HasErrors())
				{
					Globals.Message.ShowError(stocktake.WS_OH_ClientInfo.GetErrors().GetFirstMessage());
				}
				else
				{
					var userAgreedToLoadLines = false;
					try
					{
						Cursor.Current = Cursors.WaitCursor;
						userAgreedToLoadLines = stocktake.Load(this);
					}
					finally
					{
						Cursor.Current = Cursors.Default;
					}

					if (!stocktake.IsLoaded)
					{
						if (userAgreedToLoadLines)
						{
							Globals.Message.ShowError(Res.GetString("10a410f2-7e21-47d9-9312-fe16a82658e7", "There is no inventory which matches this criteria"));
						}
						// if userAgreedToLoadLines == false, than user chose not to load stocktake lines (because of number of lines) so we do nothing
						// and allow user to add more filters before trying again
					}
					else
					{
						ShowOrHideCustomsColumns(stocktake);
						LinesTabControl.SelectedTab = LinesTabControl.GetTabPage("LinesTabPage");
						NewCountMenuItem.Enabled = true;
						AssignAllLinesToUser.Enabled = true;
					}
				}

				whsStocktakeProductFilterGrid1.ShowAttachButton = !stocktake.FilterMustBeReadonly;
				whsStocktakeProductFilterGrid1.ShowDetachButton = !stocktake.FilterMustBeReadonly;
			}
			else
			{
				Globals.Message.ShowError(Res.GetString("aba11366-181b-456b-bed5-e431580f9682", "This Stocktake/Cycle Count has been loaded. It cannot be loaded again."));
			}
		}

		void ShowOrHideCustomsColumns(WhsStocktake stocktake)
		{
			bool isBondedWarehouse = stocktake.IsBondedWarehouse;
			Grid.SetColumnsAvailability(isBondedWarehouse, new[] { WhsStocktakeLineSchema.Constants.WU_BondedEntryKey });

			Grid.SetColumnsAvailability(isBondedWarehouse && stocktake.CountryCode == Constants.CountryCodes.UnitedStates,
				new[] { WhsStocktakeLineSchema.Constants.WU_PackageGroupId, WhsStocktakeLineSchema.Constants.WU_PerPackageQty });
		}

		#endregion

		#region NewCountMenuItem_Clicked

		void NewCountMenuItem_Clicked(object sender, EventArgs e)
		{
			if (Stocktake.HasChanges)
			{
				Globals.Message.ShowError(Res.GetString("ee5ee1e3-27e9-4df5-8262-71498a581fb9", "Please save all changes before adding a new count column."));
			}
			else
			{
				var caption = Res.GetString("8f5cb56d-371a-444a-a6cc-38710c4811da", "Add new count column");
				if (Stocktake.IsMaximumAmountOfColumnsAdded)
				{
					var message = Res.GetString("7ec160d5-74d3-4bcf-826b-e7678716f882", "Maximum number of count columns has already been added.");
					Globals.Message.ShowError(message, caption);
					UpdateColumnReadOnlyAndRefreshForm();
				}
				else
				{
					var message = Res.GetString("426b4d0a-b66d-47ba-b181-8f655d5792b8", "All open lines will require count data to be entered, this action cannot be undone.");
					var result = Globals.Message.Show(message, caption, MessageBoxButtons.OKCancel, MessageBoxIcon.Warning);
					if (result == DialogResult.OK)
					{
						foreach (var line in Stocktake.Lines.Where(l => l.WU_Status == StocktakeLineStatus.Codes.Open))
						{
							line.WU_TotalCounts++;
						}

						Stocktake.Factory.Save();
						UpdateColumnReadOnlyAndRefreshForm();
					}
				}
			}
		}

		void UpdateColumnReadOnlyAndRefreshForm()
		{
			SetColumnsVisibleAndReadonly();
			DisableNewCountMenuItem();

			var grid = Grid;
			grid.OrderCountColumns();
			grid.Refresh();
		}

		#endregion

		#region Status Changed

		void WS_StocktakeStatusInfo_ValueChanged(object sender, EventArgs e)
		{
			var stocktake = Stocktake;
			if (stocktake.IsFinalised)
			{
				if (NewCountMenuItem != null)
				{
					NewCountMenuItem.Enabled = false;
				}

				if (AssignAllLinesToUser != null)
				{
					AssignAllLinesToUser.Enabled = false;
				}

				if (LoadButton != null)
				{
					LoadButton.Enabled = false;
				}
			}

			StocktakeFilterStipUserControl.Grid.ReadOnly = !stocktake.IsLoaded;
		}

